INSERT INTO `incident_report` (`id`, `email_address`, `employee_id`, `full_name`, `department`, `supervisor`, `operation_manager`, `infraction`, `reported_by`, `position`, `date_of_incident`, `shift`, `incident_details`, `evidence`, `created_at`, `related_record_id`, `related_record_type`) VALUES
(93, 'nicolo.galinato@communixinc.com', 'CXI11551', 'PANGANIBAN, CHRISTIAN DAVEN', 'BNSF', 'SOROSORO, EDNETH JOHN', 'FRED BIER', 'ATTENDANCE - Absences WITHOUT Notification', 'SLT NICO', 'SLT', '2025-10-29', '2:00 AM - 11:00 AM', 'Date of Absence: October 29, 2025\nShift: 2:00 AM - 11:00 AM\nReason: DUE TO MY LIVE IN PARTNER IS STILL ADMITTED AT THE HOSPITAL DUE TO GIVING BIRTH TO OUR CHILD\nCall-in Procedure: NO', '', '2025-11-04 17:00:16', 1505, 'absenteeism'),
(94, 'nicolo.galinato@communixinc.com', 'CXI11899', 'GALINATO, NICO', 'SLT', 'TORRES, JUAN CARLO', 'Phay Barrameda', 'ATTENDANCE - Absences WITHOUT Notification', 'SLT NICO', 'SLT', '2025-11-05', '5:00 PM - 2:00 AM', 'asd', '', '2025-11-04 17:24:09', NULL, NULL),
(95, 'nicolo.galinato@communixinc.com', 'CXI11899', 'GALINATO, NICO', 'SLT', 'TORRES, JUAN CARLO', 'Phay Barrameda', 'ATTENDANCE - Absences WITHOUT Notification', 'SLT NICO', 'SLT', '2025-11-06', '5:00 PM - 2:00 AM', 'asd', '', '2025-11-04 17:38:24', NULL, NULL);
INSERT INTO `infractions` (`id`, `rule_section`, `nature_of_offense`, `stipulation`, `specific_offenses`, `first_instance`, `second_instance`, `third_instance`, `fourth_instance`, `date_created`) VALUES
(1, 'RULE I Section 1-A', 'TARDINESS', 'A', 'Three (3) instances of tardiness or at least thirty (30) minutes of accumulated tardiness within 30 days shall warrant a first notice, then every  succeeding tardiness will be taken as per instance basis.', 'VERBAL WARNING', 'WRITTEN WARNING', 'FINAL WRITTEN WARNING WITH 5 DAYS SUSPENSION', 'DISMISSAL', '2025-10-31 00:01:20'),
(2, 'RULE I- Section 1-B', 'TARDINESS', 'B', 'An employee who is required to work at a given schedule on his/her 6th working day shall be considered tardy if he/she reports for work after the start of the official work schedule. Since additional compensation for the 6th working day is based on actual hours worked, there shall be no corresponding tardiness deduction during this period. However, the tardiness shall be subject to disciplinary action.', 'VERBAL WARNING', 'WRITTEN WARNING', 'FINAL WRITTEN WARNING WITH 5 DAYS SUSPENSION', 'DISMISSAL', '2025-10-31 00:38:15'),
(3, 'RULE I- Section 2-A', 'ABSENCE WITHOUT NOTIFICATION', 'A', '1-2 consecutive days No Call No Show (NCNS) / Absence Without Official Leave (AWOL) and / or failure to report for work and advise immediate superior regarding the absence within 4 hours before the scheduled shift or schedule.\r\n1. Employee does not arrive at work and does not communicate absence at all\r\n2. Refusal to report on its expected back to work based on the filed application form for a leave of absence.', 'FINAL WRITTEN WARNING WITH 5 DAYS SUSPENSION', 'DISMISSAL', '', '', '2025-10-31 00:38:46'),
(4, 'RULE I- Section 2-B', 'ABSENCE WITHOUT NOTIFICATION', 'B', '3 days (or more) No Call No Show (NCNS) / Absence Without Official Leave (AWOL) and / or failure to report for work and advise immediate superior regarding the absence within 4 hours before the scheduled shift or schedule.\r\n\r\n1. Employee doesnt arrive at work and doesnt communicate absence at all\r\n2. Refusal to report on its expected back to work based on the filed application form for a leave of absence.', 'DISMISSAL', '', '', '', '2025-10-31 00:39:05'),
(5, 'RULE I- Section 3', 'ABSENCE WITH NOTIFICATION\r\n(4 Hrs before the shift)', '3', 'ABSENCE WITH NOTIFICATION (4 Hrs before the shift)/ Unauthorized Absence.\r\nAbsences without valid supporting documents such as but not limited to, medical\r\ncertificate, police reports and the likes.\r\nb. Sanction for absences with notification for consecutive days\r\n1. VW - 1-2 Days consecutive\r\n2. WW - 3-5 Days consecutive\r\n3. FWW w/ 5days suspension - 6-10days consecutive days\r\n4. D - 11 days or more (consecutive days)', 'VERBAL WARNING', 'WRITTEN WARNING', 'FINAL WRITTEN WARNING WITH 5 DAYS SUSPENSION', 'DISMISSAL', '2025-10-31 00:39:37'),
(6, 'RULE I- Section 4-A', 'Non-adherence to prescribed work schedule, such as, but not limited to the following:', 'A', 'Failure to complete the required number of work hours. This includes leaving the work area, assignment, duty station or going outside Company premises during designated work hours.', 'VERBAL WARNING', 'WRITTEN WARNING', 'FINAL WRITTEN WARNING WITH 5 DAYS SUSPENSION', 'DISMISSAL', '2025-10-31 00:40:15'),
(7, 'RULE I-Section 4-B', 'Non-adherence to prescribed work schedule, such as, but not limited to the following:', 'B', 'Over Break/Over Lunch – Three (3) instances of over break within 30 days OR EVERY 30 MINUTES CUMULATIVE TIME shall BE CONSIDERED ONE (1) INSTANCE', 'VERBAL WARNING', 'WRITTEN WARNING', 'FINAL WRITTEN WARNING WITH 5 DAYS SUSPENSION', 'DISMISSAL', '2025-10-31 00:40:36'),
(8, 'RULE I-Section 5', 'Abandonment of post and Other causes analogous to the foregoing', '5', 'Abandonment of post and Other causes analogous to the foregoing', 'FINAL WRITTEN WARNING WITH 5 DAYS SUSPENSION', 'DISMISSAL', '', '', '2025-10-31 00:42:49'),
(9, 'RULE I-Section 6', 'CRITICAL WORKING DAY', '6', 'CRITICAL WORKDAY- ANY ABSENCE DURING A CRITICAL WORKDAY, WHETHER JUSTIFIED OR NOT, MERITS DISCIPLINARY ACTION.\r\n\r\nCritical Work Days are defined as follows:\r\n• Philippine Holidays (legal and special holidays)\r\n• Paydays – every 10th and 25th of the month\r\n• Day before and after a rest day\r\n• Day before and after vacation leaves \r\n• Days declared by Operations', 'WRITTEN WARNING', 'FINAL WRITTEN WARNING WITH 5 DAYS SUSPENSION', 'DISMISSAL', '', '2025-10-31 00:43:05');
